def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--c1', required=True)
    parser.add_argument('--c2', required=True)
    parser.add_argument('--rev', required=True)
    args = parser.parse_args()
    for subject in ('c1', 'c2'):
        try:
            actual = normalized_dump(Path(getattr(args, subject)).read_bytes())
        except (OSError, SyntaxError, ValueError, UnicodeError) as error:
            print('NORM_PIN %s unreadable: %s' % (subject, error))
            return 1
        if actual != PINS[subject]:
            print('NORM_PIN %s MISMATCH' % subject)
            return 1
    print('NORM_PIN both normalized pristine AST dumps match')
    return 0


if __name__ == '__main__':
    sys.exit(main())
